-- Sync the discovery-pipeline backlog into the real /admin/review queue,
-- round 2 (2026-10-12, direct user request: "push through all venue and
-- district research for me to review"). Same pattern as migration 0041:
-- 94 venue + 3 district candidates below are the net-new
-- backlog from docs/data/venue-suggestions.json/district-suggestions.json's
-- own "pending" entries, cross-checked by name against both the live
-- venues/districts tables and the existing venue_candidates/
-- district_candidates rows so nothing already pushed (0041) or already
-- promoted (the moment-categories work's Lymm/Ramsbottom/Monton) gets
-- duplicated — the suggestion JSON files themselves were never updated to
-- reflect those outcomes (fixed separately, same date, by patching their
-- status/researchNotes fields directly rather than re-serializing either
-- file). One genuine duplicate within the backlog itself ("Mielle",
-- Ancoats, independently rediscovered twice 2 days apart) deduped down to
-- its more corroborated entry before this migration was generated.

insert into venue_candidates (
  name, type, sub_preference_tags, spend_level, district_id, metro,
  lat, lon, pet_friendly, dietary_options, photos, description, bands, base,
  gate1_reasoning, distinctiveness_proposed, ownership, ownership_evidence,
  sources, status
) values
  ('Colin Jellicoe Gallery', 'ART GALLERY', '{}', 1, 'chinatown', 'manchester', 53.4782, -2.2393, false, '{none}', '{}', 'Sixty years of the same independent eye on Portland Street, still hanging shows the gallery''s late founder would have approved of — one of the longest-running galleries in the city, and one of the quietest.', '{"afternoon"}', 66, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-09-30 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('A.T. Welch', 'BRUNCH SPOT', '{}', 1, 'nantwich', 'cheshire', 53.0662, -2.5197, false, '{none}', '{}', 'Walk through the working pork butcher''s counter to find the café at the back — fourth-generation Austins, a replica 1940s grocery still standing behind it, and a full breakfast served on china that''s never once been swapped for paper plates.', '{"morning","afternoon"}', 62, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-09-30 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Libero', 'ALE HOUSE', '{}', 1, 'altrincham', 'cheshire', 53.3851, -2.3518, false, '{none}', '{}', 'Sixteen seats and a craft-only tap list in a Kings Court unit the size of a front room — Rooney''s been running it long enough that the football crowd never had to be told twice where to go.', '{"afternoon","evening","late"}', 64, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-09-30 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Prestbury Farm Shop', 'FARM SHOP', '{}', 2, 'prestbury', 'cheshire', 53.2893, -2.1516, false, '{none}', '{}', 'Free-range game and fish landed that morning, sold from the same corner of The Village for longer than most of Prestbury''s restaurants have existed — the village''s actual larder, not a gift-shop version of one.', '{"morning","afternoon"}', 58, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-09-30 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('One Thirty Cafe & Bar', 'COFFEE ROOM', '{}', 2, 'cheadle-hulme', 'cheshire', 53.3667, -2.19, false, '{none}', '{}', 'A family-run counter on Hulme Hall Road that pours prosecco and bottled beer alongside the flat whites — Cheadle Hulme''s daytime answer to a proper bar, gone by mid-afternoon rather than staying open just to prove a point.', '{"morning","afternoon"}', 60, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-09-30 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Dahlia Stereo', 'SMOKEHOUSE', '{}', 3, 'northern-quarter', 'manchester', 53.4831, -2.2333, false, '{none}', '{}', 'Open-fire barbacoa on the ground floor, a mezcal and tequila liquorita built into the bar itself, and a sound system upstairs curated by two Manchester DJs who never needed the introduction — dinner doesn''t have to end when the plates do.', '{"evening","late"}', 76, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-09-30 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Maricarmen', 'SMALL PLATES', '{}', 2, 'ancoats', 'manchester', 53.4834, -2.22973, false, '{none}', '{}', 'José Núñez''s tapas started as a Friday-night pop-up inside an Ancoats chocolate shop before it earned its own address — the queue moved with it, and a second room in the Northern Quarter hasn''t thinned it out.', '{"afternoon","evening"}', 74, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-09-30 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Convene', 'BRUNCH SPOT', '{}', 2, 'stockport-underbanks', 'manchester', 53.4103, -2.1558, false, '{none}', '{}', 'Isabella Cubrilo swapped her Balkan Bible supper club for a permanent stove on Lower Hillgate — a seasonal menu that changes before regulars get bored of it, and a coffee counter that means nobody''s just passing through.', '{"morning","afternoon"}', 68, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-09-30 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Bottle', 'BOTTLE SHOP', '{}', 1, 'heaton-moor', 'manchester', 53.4232, -2.1855, false, '{none}', '{}', 'Ten taps and a suntrap garden on Shaw Road since 2015 — Corin Bland''s own shop, open years before he took on the Market Hall''s beer hall in town, and still the one worth sitting down in.', '{"afternoon","evening"}', 62, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-09-30 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Dear Sailor', 'COCKTAIL BAR', '{}', 3, 'spinningfields', 'manchester', 53.480116, -2.249547, false, '{none}', '{}', 'A 1930s Tokyo drinking den dropped into Spinningfields Square, with its own strict list of house rules and a terrace that empties into DJ-led lock-ins once the sun''s gone.', '{"evening","late"}', 80, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-01 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('The Badger', 'GASTROPUB', '{}', 2, 'northern-quarter', 'manchester', 53.481522, -2.234004, false, '{none}', '{}', 'The Crown & Kettle team''s third room, on Dale Street — taxidermy and Dickensian corners dressed up around a pie that''s the actual reason to stay past the first drink.', '{"afternoon","evening","late"}', 74, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-01 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Marleo', 'BAKERY', '{}', 1, 'northern-quarter', 'manchester', 53.483636, -2.234515, false, '{none}', '{}', 'Maria and Leo''s Sicilian counter graduated from a shipping container in Pollard Yard to its own shopfront on Oldham Street — focaccia and arancini that never needed the upgrade to taste right.', '{"morning","afternoon"}', 64, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-01 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Nixons Farm Shop', 'FARM SHOP', '{}', 2, 'cheadle-hulme', 'cheshire', 53.360849, -2.230924, false, '{none}', '{}', 'Three Nixon grandchildren still run the farm their family has worked since the 1930s — a proper butcher''s counter and a slaughterhouse history behind it, not a gift-shop version of a farm shop.', '{"morning","afternoon"}', 60, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-01 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('House of Esk', 'WINE BAR', '{}', 3, 'ancoats', 'manchester', 53.483769, -2.224689, false, '{none}', '{}', 'Emma''s room on Islington Marina knows the regulars by name and what they''re drinking before they say it — natural wine and cocktails with the water close enough to hear from the terrace.', '{"afternoon","evening","late"}', 74, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-01 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('The Cheshire Tap', 'ALE HOUSE', '{}', 1, 'altrincham', 'cheshire', 53.385137, -2.351828, false, '{none}', '{}', 'Family-run since 2018, four hand-pumps and a rear garden tucked into King''s Court — a community bar built around the local breweries rather than whichever cask the distributor pushed that week.', '{"afternoon","evening","late"}', 68, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-01 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Batch Bottlestore', 'BOTTLE SHOP', '{}', 1, 'altrincham', 'cheshire', 53.384893, -2.351995, false, '{none}', '{}', 'Chris and Will left the Shaw''s Road bar they''d run for five years and filled a King''s Court unit with 250-odd craft beers and the town''s biggest natural wine range — drink in or take it home, either way.', '{"afternoon","evening"}', 64, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-01 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Edencroft Fine Wines', 'WINE MERCHANT', '{}', 3, 'nantwich', 'cheshire', 53.066291, -2.521454, false, '{none}', '{}', 'Mark Brookshaw has run the counter on Hospital Street since 1994 — a whisky education as thorough as the wine list, and neither one chasing whatever the trade press called ''the next big thing'' this year.', '{"afternoon","evening"}', 70, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-01 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Board Beans Cafe', 'GAMES CAFE', '{}', 1, 'northwich', 'cheshire', 53.2622, -2.5111, false, '{none}', '{}', 'Frazer and Becka''s shelf runs to three hundred-odd board games on Witton Street — order the coffee, pick a box, and nobody''s rushing the table back for the next sitting.', '{"morning","afternoon","evening"}', 60, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-01 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('The Westgate', 'COCKTAIL BAR', '{}', 3, 'hale', 'cheshire', 53.377037, -2.346064, false, '{none}', '{}', 'The Elk''s own team a few doors down Ashley Road, built for a ''weird and wonderful'' cocktail list rather than a reliable classic — dark, gold-lit, and speakeasy-leaning without the theatre of an actual password.', '{"evening","late"}', 75, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-01 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Cassidys', 'LIVE MUSIC BAR', '{}', 2, 'heaton-moor', 'manchester', 53.4232, -2.1855, false, '{none}', '{}', 'Two decades of Guinness poured properly and a stage close enough to touch on a Saturday — Heaton Moor''s actual Irish pub, not a theme.', '{"evening","late"}', 66, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-03 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Courtyard Coffee House', 'BRUNCH SPOT', '{}', 1, 'knutsford', 'cheshire', 53.305008, -2.373843, false, '{none}', '{}', 'Tucked behind King Street''s own shopfronts, the kind of courtyard you only find once — and the kind of brunch that makes finding it again worth the detour.', '{"morning","afternoon"}', 64, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-03 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Romulus', 'ITALIAN RESTAURANT', '{}', 2, 'bramhall', 'cheshire', 53.357038, -2.166057, false, '{none}', '{}', 'Salvatore''s run the same Woodford Road room for thirty years, and the village still asks for his table by name, not the menu''s.', '{"afternoon","evening"}', 70, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-03 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Queer Lit', 'BOOKSHOP', '{}', 1, 'ancoats', 'manchester', 53.4813, -2.2258, false, '{none}', '{}', 'Four and a half thousand titles under one Great Ancoats Street roof, catalogued by people who actually read them — Europe''s largest LGBTQ+ bookshop, not a corner shelf anywhere else.', '{"afternoon"}', 70, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-03 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Temple Bar', 'ALE HOUSE', '{}', 2, 'northwich', 'cheshire', 53.2622, -2.5115, false, '{none}', '{}', 'Charlotte Mills came home to open the bar Northwich''s high street was missing — cask ale and a proper cocktail list behind a front door that used to belong to someone else''s chain.', '{"afternoon","evening"}', 68, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-03 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('The Liquor Store', 'LATE-NIGHT LOUNGE', '{}', 3, 'deansgate', 'manchester', 53.483594, -2.247073, false, '{none}', '{}', 'A vintage LA liquor-store fit-out behind Blackfriars Street''s own front door, pouring award-winning cocktails to a soundtrack that doesn''t quiet down until three.', '{"evening","late"}', 78, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-03 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('The Elk of Didsbury', 'COCKTAIL BAR', '{}', 2, 'didsbury', 'manchester', 53.4264, -2.2433, false, '{none}', '{}', 'A smartly converted corner pub on Burton Road where craft beer and proper cocktails share the same short list — the quieter sibling to the original on Ashley Road, run the same unfussy way.', '{"evening","late"}', 76, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-03 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Stow', 'SMALL PLATES', '{}', 3, 'spinningfields', 'manchester', 53.480871, -2.249461, false, '{none}', '{}', 'Nothing in the kitchen runs on gas — every plate on Bridge Street comes off live fire, and the Michelin inspectors noticed before most of Manchester did.', '{"evening","late"}', 88, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-03 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('The Jolly Gardeners', 'GASTROPUB', '{}', 3, 'chester', 'cheshire', 53.1917, -2.8703, false, '{none}', '{}', 'Ben and Joe Wright''s third room, a Boughton freehouse with no brewery tie and a 2026 Michelin Guide listing earned on the kitchen alone, not the postcode.', '{"afternoon","evening"}', 82, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-03 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Layla''s', 'BRUNCH SPOT', '{}', 2, 'deansgate', 'manchester', 53.474845, -2.256192, false, '{none}', '{}', 'Sarah''s canalside room on Catalan Square, next door to her own Barça — Middle Eastern plates alongside the full English, with the towpath close enough to eat on.', '{"morning","afternoon"}', 74, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-04 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Bombay to Mumbai', 'INDIAN RESTAURANT', '{}', 2, 'bramhall', 'cheshire', 53.3714, -2.1588, false, '{none}', '{}', 'Sandeep''s regional Indian cooking on Fir Road turns ordering into the night''s real decision — a genuinely different dish from a different corner of the subcontinent on every page, not one house curry wearing several names.', '{"evening"}', 78, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-04 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Black Bush', 'IRISH BAR', '{}', 2, 'chester', 'cheshire', 53.187863, -2.890338, false, '{none}', '{}', 'A Northern Irish landlord''s own undercroft bar beneath Gamul House, no theme beyond a properly poured pint — the regulars'' own verdict is the best Guinness on Lower Bridge Street, and nobody''s arguing.', '{"evening","late"}', 76, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-04 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Northgates', 'COCKTAIL BAR', '{}', 2, 'chester', 'cheshire', 53.1929, -2.8925, false, '{none}', '{}', 'Tony''s cocktail room on Northgate Street grew out of his own market stall selling healthy snacks — small plates built around sustainability, and live music most Fridays once the bar''s properly warmed up.', '{"afternoon","evening","late"}', 72, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-04 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Alison Bradley Gallery', 'ART GALLERY', '{}', 1, 'chester', 'cheshire', 53.1901, -2.8935, false, '{none}', '{}', 'Alison''s own charcoal drawings and oil landscapes line a Watergate Street townhouse, framed on site by the same two hands — her partner Jon — who hung them.', '{"morning","afternoon"}', 66, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-04 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('La Famiglia', 'ITALIAN RESTAURANT', '{}', 2, 'hale', 'cheshire', 53.378859, -2.346951, false, '{none}', '{}', 'Pino Malena''s Calabrian kitchen on Victoria Road, close on four decades of regulars who''ve long since stopped needing to open the menu to know what they''re having.', '{"afternoon","evening"}', 74, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-04 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Owen''s Kitchen & Bar', 'GASTROPUB', '{}', 2, 'hale', 'cheshire', 53.378548, -2.349038, false, '{none}', '{}', 'Ritchie Bagnall named his second room after the same grandfather as the Urmston original — a proper Sunday roast and no pretence on Ashley Road, the kind of hospitality that doesn''t need a tasting menu to prove itself.', '{"afternoon","evening"}', 72, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-04 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Lion Salt Works', 'HERITAGE CENTRE', '{}', 1, 'northwich', 'cheshire', 53.27714, -2.49384, false, '{none}', '{}', 'The last open-pan salt works left in the country, a couple of miles up Ollershaw Lane from the quayside bars — brine tanks and a manager''s cottage left exactly as the works left them when the pans went cold in 1986.', '{"morning","afternoon"}', 62, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-10-04 — not yet independently re-verified by a second review pass. Synced 2026-10-12 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
